import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

export default function createNode(config, ctx) {
  // --- Geometry ---
  const geometry = new THREE.PlaneGeometry(1, 1);

  // --- Texture ---
  const tex = ctx.textureLoader(config.assets?.imageUrl ?? '');

  // Enable texture orientation handling if needed
  tex.flipY = false;
  tex.needsUpdate = true;

  // --- Material ---
  const material = new MeshBasicNodeMaterial({
    map: tex,
    transparent: true,
    alphaTest: 0.0,
    depthWrite: true,
    depthTest: true,
  });

  // --- Mesh ---
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = config.id ?? 'journal-card-1';

  // --- Placement ---
  const pos = config.scenePlacement?.position ?? [0, 0, 0];
  const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
  const scl = config.scenePlacement?.scale ?? [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // --- Apply cinematic primitives if any ---
  const primitivesList = config.cinematicPrimitives ?? [];
  for (const prim of primitivesList) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      fn(mesh, prim.params);
    }
  }

  // --- UserData for handlers & cleanup ---
  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    // Dispose GSAP timelines (none for this node, but guard for future)
    gsap.globalTimeline.clear();

    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  return mesh;
}
